(447, 'WorldsCollide4guse', '20111104044044', 'Worlds Collide', 55024, 0, 'Guristas forces have been reported in a deadspace pocket.  Eliminate every last one of them.  Expect Kin, Therm damage.', 4, 2, 0, 0, 500010, 0, 1, 0, 0, 101000447, 2, 0, 0, 0, 1.00, 1, 1, 1),
(448, 'WorldsCollide4saga', '20111123075749', 'Worlds Collide', 55024, 0, 'Sansha''s Nation forces have been reported in a deadspace pocket.  Eliminate every last one of them.  Expect Ki/Th from Gallente, EM/Th from Sansha damage.', 4, 2, 0, 0, 500019, 0, 1, 0, 0, 101000448, 2, 0, 0, 0, 1.00, 1, 1, 1),
(449, 'WorldsCollide4segu', '20110904130804', 'Worlds Collide', 55024, 0, 'Guristas forces have been reported in a deadspace pocket.  Eliminate every last one of them.  Expect (Kin, Therm - for Guristas) damage.', 4, 2, 0, 0, 500010, 0, 1, 0, 0, 101000449, 2, 0, 0, 0, 1.00, 1, 1, 1);
